/* Vextra blocks – 10. Microphone (6), 11. Camera (6), 12. VR (7), 13. AR (7).
 * Services live in rt-sensors.js. Every block has a desktop/test fallback so games can be designed without a headset or camera. */
(function () {
  const VXRT = window.VXRT, U = VXRT.util, B = VXRT.registerBlock, P = VXRT.P, SN = () => VXRT.sense;
  const oname = (g, n) => { try { return g.targets(n.p.target || 'self', n.owner, n.owner.lastOther); } catch { return []; } };
  const rad = (o) => 0.5 * Math.max(o.w || 1, o.h || 1, o.d || 1);
  const pos = (o) => ({ x: o.x || 0, y: o.y || 0, z: o.z || 0 });
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
  const fail = (n, g, e) => { const m = (e && e.message) || String(e); g.send(n, 'error', m); try { g.log('warn', '[sensors] ' + m); } catch { /* no log */ } if (g.debug && console) console.warn('[Vextra sensors] ' + m); };
  const objs = (g, n, key, self) => g.targets(n.p[key] || '', self || n.owner, n.owner.lastOther).filter((o) => o.alive);
  const edge = (n, k, v) => { const was = !!n.st[k]; n.st[k] = !!v; return v && !was ? 1 : !v && was ? -1 : 0; };
  const headRay = (g) => { const S = SN(), v = S.state(g).vr, a = S.state(g).ar; let p, yaw, pit; if (v.active) { S.vrFrame(g); p = { x: v.head.x, y: v.head.y, z: v.head.z }; yaw = (v.mode === 'stereo' ? g.cam3d.yaw + v.rig.yaw : 0) + v.head.yaw; pit = v.head.pitch; if (v.mode === 'webxr') { yaw = v.head.yaw; } } else { p = a.cam || g.cam3d.pos; yaw = g.cam3d.yaw + (a.head ? a.head.yaw : 0); pit = a.head ? a.head.pitch : g.cam3d.pitch || 0; } const y = U.rad(yaw), q = U.rad(pit); return { pos: p, dir: { x: -Math.sin(y) * Math.cos(q), y: Math.sin(q), z: -Math.cos(y) * Math.cos(q) } }; };
  const rayHit = (ray, o) => { const c = pos(o), r = rad(o) * (o.scale || 1), ox = c.x - ray.pos.x, oy = c.y - ray.pos.y, oz = c.z - ray.pos.z, t = ox * ray.dir.x + oy * ray.dir.y + oz * ray.dir.z; if (t < 0) return false; const px = ray.pos.x + ray.dir.x * t - c.x, py = ray.pos.y + ray.dir.y * t - c.y, pz = ray.pos.z + ray.dir.z * t - c.z; return Math.hypot(px, py, pz) <= r; };
  const needs3d = (n, g) => { if (g.dim !== '3d') { fail(n, g, new Error('This block needs a 3D game')); return false; } return true; };
  const button = (g, id, text, fn) => { const old = g.container.querySelector('[data-vx-xrbtn="' + id + '"]'); if (old) old.remove(); const b = document.createElement('button'); b.textContent = text; b.setAttribute('data-vx-xrbtn', id); b.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:40;padding:10px 22px;border-radius:999px;border:2px solid #fff;background:#0009;color:#fff;font:600 15px system-ui;cursor:pointer'; b.onclick = fn; g.container.append(b); return b; };

  /* ======================= 10. Microphone ======================= */
  B({ id: 'microphone', cat: 'mic', label: 'Microphone', desc: 'Listens to the microphone: loudness (0–100), pitch (Hz) and low / mid / high sound, every frame. Use the level to steer a game with your voice, make a bar grow while you shout, or fire "loud" / "quiet". Needs the player\'s permission. If there is no microphone, hold the test key (default M) to pretend you are making noise.',
    inputs: ['start', 'stop', 'toggle'], outputs: ['out', 'level', 'pitch', 'loud', 'quiet', 'ready', 'error'],
    params: [P.bool('auto', 'Start automatically', true), P.num('gain', 'Sensitivity', 1, { min: 0.1, max: 8, step: 0.1 }), P.num('loudAt', 'Loud above (%)', 40, { min: 1, max: 100 }), P.num('smooth', 'Smoothing 0–0.95', 0.4, { min: 0, max: 0.95, step: 0.05 }), P.text('variable', 'Save level (0–100) in variable', ''), P.text('testKey', 'Test key (no microphone)', 'm')],
    init(n, g) { n.st.on = false; n.st.held = false; n.st.lvl = 0; n.cleanups.push(() => { if (n.st.held) { SN().micRelease(g); n.st.held = false; } }); if (n.p.auto) this.onInput(n, 'start', null, g); },
    onInput(n, port, v, g) { const S = SN(); if (port === 'toggle') port = n.st.on ? 'stop' : 'start';
      if (port === 'start' && !n.st.held) { n.st.held = true; S.micAcquire(g).then(() => { n.st.on = true; g.send(n, 'ready', true); }).catch((e) => { n.st.held = false; n.st.sim = true; fail(n, g, e); }); }
      if (port === 'stop' && n.st.held) { S.micRelease(g); n.st.held = false; n.st.on = false; } },
    update(n, dt, g) { const S = SN(); let r = n.st.on ? S.micRead(g, U.num(n.p.gain, 1)) : null; if (!r && n.p.testKey && g.input.isDown(String(n.p.testKey).toLowerCase())) r = { level: 0.8, pitch: 220, low: 0.6, mid: 0.4, high: 0.1, peak: 0.9, db: -10 }; if (!r && !n.st.on && !n.st.sim) return; if (!r) r = { level: 0, pitch: 0, low: 0, mid: 0, high: 0, peak: 0, db: -100 };
      const k = U.clamp(U.num(n.p.smooth, 0.4), 0, 0.95); n.st.lvl = n.st.lvl * k + r.level * (1 - k); const lvl = Math.round(n.st.lvl * 100); if (n.p.variable) g.vars[n.p.variable] = lvl;
      g.send(n, 'level', lvl); if (r.pitch) g.send(n, 'pitch', Math.round(r.pitch)); g.send(n, 'out', { level: lvl, pitch: Math.round(r.pitch), low: r.low, mid: r.mid, high: r.high });
      const e = edge(n, 'isLoud', lvl >= U.num(n.p.loudAt, 40)); if (e > 0) g.send(n, 'loud', lvl); else if (e < 0) g.send(n, 'quiet', lvl); } });

  B({ id: 'voiceCommand', cat: 'mic', label: 'Voice Command', desc: 'Listens for spoken words and fires the matching exit. Type one command per line (e.g. jump / fire / stop) – each becomes its own exit. "heard" sends everything recognised, "none" sends speech that matched nothing. Uses the browser\'s speech recognition (Chrome, Edge, Safari and most mobile browsers; needs internet). In the desktop app, whose engine has no speech service, add a speech-to-text service in Settings → Voice commands. The "say" entry lets you test by sending text.',
    inputs: ['start', 'stop', 'say'], outputs: (p) => ['out', 'heard', 'none', 'error', ...String(p.commands || '').split(/[\n,]+/).map((s) => s.trim().toLowerCase()).filter((s, i, a) => s && a.indexOf(s) === i && !['out', 'heard', 'none', 'error'].includes(s))],
    params: [P.area('commands', 'Commands (one per line)', 'jump\nfire\nstop'), P.text('lang', 'Language', 'en-US', { hint: 'en-US, en-GB, es-ES, fr-FR, de-DE, ja-JP …' }), P.sel('match', 'Match', [['contains', 'Contains the word'], ['exact', 'Exactly'], ['starts', 'Starts with']], 'contains'), P.bool('interim', 'React while still speaking (faster)', true), P.bool('auto', 'Start automatically', true), P.text('variable', 'Save last heard text in variable', '')],
    init(n, g) { n.cleanups.push(() => { if (n.st.h) n.st.h.stop(); }); if (n.p.auto) this.onInput(n, 'start', null, g); },
    handle(n, g, text, final) { if (!text) return; const t = text.toLowerCase(); if (n.p.variable) g.vars[n.p.variable] = text; if (final || n.p.interim) g.send(n, 'heard', text);
      const list = String(n.p.commands || '').split(/[\n,]+/).map((s) => s.trim().toLowerCase()).filter(Boolean); const m = n.p.match; const hit = list.find((c) => (m === 'exact' ? t === c : m === 'starts' ? t.startsWith(c) : new RegExp('(^|\\W)' + c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(\\W|$)').test(t)));
      if (hit && !n.st.fired) { n.st.fired = true; g.send(n, hit, text); g.send(n, 'out', hit); } else if (!hit && final) g.send(n, 'none', text); if (final) n.st.fired = false; },
    onInput(n, port, v, g) { if (port === 'say') return this.handle(n, g, String(v ?? ''), true); if (port === 'stop') { if (n.st.h) { n.st.h.stop(); n.st.h = null; } return; }
      if (port === 'start' && !n.st.h) { n.st.h = SN().speech({ lang: n.p.lang, interim: n.p.interim }, (t, fin) => this.handle(n, g, t, fin), (s, e) => { if (s === 'error') fail(n, g, new Error('Speech recognition: ' + e)); }, g); if (!n.st.h) fail(n, g, new Error('Speech recognition is not available in this browser – use the "say" entry to test.')); } } });

  B({ id: 'soundDetector', cat: 'mic', label: 'Sound Detector', desc: 'Recognises kinds of sound from the microphone: a clap (or double clap), a whistle, a shout, a loud noise and silence. Great for "clap to turn on the light" or "whistle to call the dog". No microphone? Test keys: C clap, B whistle, V shout.',
    inputs: ['start', 'stop'], outputs: ['clap', 'doubleClap', 'whistle', 'shout', 'loud', 'silence', 'error'],
    params: [P.num('gain', 'Sensitivity', 1, { min: 0.1, max: 8, step: 0.1 }), P.num('clapAt', 'Clap sharpness (%)', 55, { min: 10, max: 100 }), P.num('whistleHz', 'Whistle above (Hz)', 900, { min: 400, max: 3000, step: 50 }), P.num('shoutAt', 'Shout above (%)', 75, { min: 20, max: 100 }), P.num('silenceFor', 'Silence after (s)', 2, { min: 0.5, step: 0.5 })],
    init(n, g) { n.st.held = true; n.st.t = { c: -9, w: -9, s: -9, l: -9 }; n.st.prev = 0; n.st.quietT = 0; SN().micAcquire(g).then(() => { n.st.on = true; }).catch((e) => { n.st.held = false; n.st.sim = true; fail(n, g, e); }); n.cleanups.push(() => { if (n.st.held) SN().micRelease(g); }); },
    onInput(n, port, v, g) { const S = SN(); if (port === 'stop' && n.st.held) { S.micRelease(g); n.st.held = false; n.st.on = false; } if (port === 'start' && !n.st.held) { n.st.held = true; S.micAcquire(g).then(() => { n.st.on = true; }).catch((e) => fail(n, g, e)); } },
    update(n, dt, g) { const S = SN(), T = g.time, t = n.st.t, I = g.input; let r = n.st.on ? S.micRead(g, U.num(n.p.gain, 1)) : null; if (!r && n.st.sim) { r = { level: 0, peak: 0, pitch: 0, high: 0, mid: 0, low: 0 }; if (I.pressed.has('c')) { r.peak = 0.95; r.level = 0.9; r.high = 0.6; r.mid = 0.6; } if (I.isDown('b')) { r.level = 0.4; r.pitch = 1800; r.high = 0.5; } if (I.isDown('v')) { r.level = 0.95; r.peak = 0.95; r.low = 0.7; r.mid = 0.7; } } if (!r) return;
      const clapAt = U.num(n.p.clapAt, 55) / 100, fire = (k, port) => { if (T - t[k] < 0.3) return false; t[k] = T; g.send(n, port || k, true); return true; };
      if (r.peak >= clapAt && n.st.prev < clapAt * 0.5 && r.high > r.low * 0.4 && r.pitch < U.num(n.p.whistleHz, 900) * 2) { if (fire('c', 'clap')) { if (T - (n.st.lastClap ?? -9) < 0.7) { g.send(n, 'doubleClap', true); n.st.lastClap = -9; } else n.st.lastClap = T; } }
      n.st.prev = r.peak; if (r.pitch >= U.num(n.p.whistleHz, 900) && r.pitch < 4000 && r.level > 0.12 && r.high >= r.low) { n.st.whistleT = (n.st.whistleT || 0) + dt; if (n.st.whistleT > 0.2) fire('w', 'whistle'); } else n.st.whistleT = 0;
      if (r.level * 100 >= U.num(n.p.shoutAt, 75)) fire('s', 'shout'); if (r.level > 0.3) fire('l', 'loud');
      if (r.level < 0.04) { n.st.quietT += dt; if (n.st.quietT >= U.num(n.p.silenceFor, 2) && !n.st.silent) { n.st.silent = true; g.send(n, 'silence', true); } } else { n.st.quietT = 0; n.st.silent = false; } } });

  B({ id: 'voiceNoise', cat: 'mic', label: 'Voice Noise', desc: 'Turns the player\'s voice into noise in the game world: the louder you are, the further away enemies with a Hearing block can hear you. Pick the object the noise comes from (usually the player). "Quiet key" halves the noise while held (sneaking). No microphone? Hold M.',
    inputs: ['start', 'stop'], outputs: ['out', 'noise', 'error'],
    params: [P.object('source', 'Noise comes from', 'self', ['self']), P.num('radius', 'Loudest range (units)', 14, { min: 1, step: 1 }), P.num('minLevel', 'Ignore below (%)', 12, { min: 0, max: 100 }), P.num('gain', 'Sensitivity', 1.2, { min: 0.1, max: 8, step: 0.1 }), P.text('quietKey', 'Quiet key (sneak)', 'shift'), P.text('testKey', 'Test key (no microphone)', 'm')],
    init(n, g) { n.st.held = true; n.st.a = 0; SN().micAcquire(g).then(() => { n.st.on = true; }).catch((e) => { n.st.held = false; n.st.sim = true; fail(n, g, e); }); n.cleanups.push(() => { if (n.st.held) SN().micRelease(g); }); },
    onInput(n, port, v, g) { const S = SN(); if (port === 'stop' && n.st.held) { S.micRelease(g); n.st.held = false; n.st.on = false; } if (port === 'start' && !n.st.held) { n.st.held = true; S.micAcquire(g).then(() => { n.st.on = true; }).catch((e) => fail(n, g, e)); } },
    update(n, dt, g) { n.st.a -= dt; if (n.st.a > 0) return; n.st.a = 0.15; let lvl = 0; const r = n.st.on ? SN().micRead(g, U.num(n.p.gain, 1.2)) : null; if (r) lvl = r.level * 100; else if (n.p.testKey && g.input.isDown(String(n.p.testKey).toLowerCase())) lvl = 80; if (lvl < U.num(n.p.minLevel, 12)) return;
      if (n.p.quietKey && g.input.isDown(String(n.p.quietKey).toLowerCase())) lvl *= 0.5; const R = U.num(n.p.radius, 14) * lvl / 100; for (const o of objs(g, n, 'source')) SN().makeNoise(g, o.x, o.y, o.z || 0, R, o); g.send(n, 'noise', Math.round(lvl)); g.send(n, 'out', R); } });

  B({ id: 'makeNoise', cat: 'mic', label: 'Make Noise', desc: 'Makes a noise at an object that enemies with a Hearing block can hear: a door slam, a thrown bottle, an explosion. Turn on "footsteps" to make noise while the object moves (sneak by moving slowly).',
    inputs: ['in'], outputs: ['out'], params: [P.object('source', 'Noise comes from', 'self', ['self']), P.num('radius', 'Range (units)', 10, { min: 0.5, step: 0.5 }), P.bool('footsteps', 'Also make footsteps while moving', false), P.num('stepSpeed', 'Footsteps need speed above', 1.5, { step: 0.1 }), P.num('stepRadius', 'Footstep range', 4, { step: 0.5 }), P.num('stepEvery', 'Footstep every (s)', 0.4, { step: 0.05 })],
    onInput(n, port, v, g) { for (const o of objs(g, n, 'source')) SN().makeNoise(g, o.x, o.y, o.z || 0, U.num(n.p.radius, 10), o); g.send(n, 'out', v); },
    update(n, dt, g) { if (!n.p.footsteps) return; n.st.t = (n.st.t || 0) - dt; if (n.st.t > 0) return; for (const o of objs(g, n, 'source')) { const sp = Math.hypot(o.vx || 0, o.vy || 0, o.vz || 0); if (sp >= U.num(n.p.stepSpeed, 1.5)) { SN().makeNoise(g, o.x, o.y, o.z || 0, U.num(n.p.stepRadius, 4) * Math.min(2, sp / 4 + 0.5), o); n.st.t = U.num(n.p.stepEvery, 0.4); } } } });

  B({ id: 'hearing', cat: 'mic', label: 'Hearing', desc: 'Gives this object ears. It hears voice noise (Voice Noise block), Make Noise blocks and footsteps within range, remembers where the sound came from, and can walk to it – an enemy that tracks the player by their voice. Exits: "heard" (new sound), x / y / z (where), "arrived" (reached the spot), "lost" (gave up).',
    inputs: ['enable', 'disable'], outputs: ['heard', 'x', 'y', 'z', 'distance', 'arrived', 'lost', 'out'],
    params: [P.num('range', 'Hearing range multiplier', 1, { min: 0.1, step: 0.1 }), P.bool('chase', 'Walk towards the sound', true), P.num('speed', 'Walking speed', 3, { step: 0.5 }), P.num('stopAt', 'Stop this close', 1.2, { step: 0.1 }), P.num('memory', 'Keeps searching for (s)', 5, { step: 0.5 }), P.bool('face', 'Turn to face it', true), P.num('faceOffset', 'Facing offset (degrees)', 0, { step: 15 }), P.bool('flat', 'Stay on the ground (ignore height)', true)],
    init(n) { n.st.on = true; n.st.seen = new WeakSet(); },
    onInput(n, port, v, g) { n.st.on = port === 'enable'; if (!n.st.on) { n.st.target = null; } },
    update(n, dt, g) { if (!n.st.on) return; const o = n.owner, S = SN(); let best = null, bd = 1e9;
      for (const q of S.noises(g)) { if (q.src === o || g.time - q.t > 0.35 || n.st.seen.has(q)) continue; const d = dist(pos(o), { x: q.x, y: q.y, z: q.z }); if (d <= q.radius * U.num(n.p.range, 1) && d < bd) { best = q; bd = d; } }
      if (best) { n.st.seen.add(best); n.st.target = { x: best.x, y: best.y, z: best.z }; n.st.t = g.time; n.st.arrived = false; g.send(n, 'x', best.x); g.send(n, 'y', best.y); g.send(n, 'z', best.z); g.send(n, 'distance', bd); g.send(n, 'out', { x: best.x, y: best.y, z: best.z, distance: bd }); g.send(n, 'heard', bd); }
      const tg = n.st.target; if (!tg) return; if (g.time - n.st.t > U.num(n.p.memory, 5)) { n.st.target = null; o.vx = 0; if (g.dim === '3d') o.vz = 0; g.send(n, 'lost', true); return; }
      const is3 = g.dim === '3d', dx = tg.x - o.x, dz = is3 ? tg.z - o.z : 0, dy = is3 && n.p.flat ? 0 : tg.y - o.y, d = Math.hypot(dx, dy, dz);
      if (d <= U.num(n.p.stopAt, 1.2)) { if (n.p.chase) { o.vx = 0; if (is3) o.vz = 0; else o.vy = 0; } if (!n.st.arrived) { n.st.arrived = true; g.send(n, 'arrived', true); } return; }
      if (n.p.face) { if (is3) o.ry = U.deg(Math.atan2(-dx, -dz)) + U.num(n.p.faceOffset, 0); else o.rot = U.deg(Math.atan2(dy, dx)) + U.num(n.p.faceOffset, 0); }
      if (n.p.chase) { const s = U.num(n.p.speed, 3); o.vx = dx / d * s; if (is3) { o.vz = dz / d * s; if (!n.p.flat) o.vy = dy / d * s; } else o.vy = dy / d * s; } } });

  /* ======================= 11. Camera ======================= */
  const camStart = (n, g) => { const S = SN(); if (n.st.camHeld) return; n.st.camHeld = true; S.camAcquire(g, n.p.facing || 'user').then(() => { n.st.cam = true; if (n.p.display) S.camShow(g, g.dim !== '3d' && n.p.display === 'behind' ? 'overlay' : n.p.display, g.dim !== '3d' && n.p.display === 'behind' ? 0.5 : n.p.opacity); g.send(n, 'ready', true); }).catch((e) => { n.st.camHeld = false; n.st.sim = true; fail(n, g, e); }); n.cleanups.push(() => { if (n.st.camHeld) { SN().camRelease(g); n.st.camHeld = false; } }); };
  const camStop = (n, g) => { if (n.st.camHeld) { SN().camRelease(g); n.st.camHeld = false; n.st.cam = false; } };
  const FACING = P.sel('facing', 'Camera', [['user', 'Front (selfie) camera'], ['environment', 'Back camera']], 'user');

  B({ id: 'cameraFeed', cat: 'webcam', label: 'Camera Feed', desc: 'Turns on the device camera and shows it: in a corner, over the whole game, or behind a 3D scene (a quick mirror or AR-style background). Other Camera blocks switch the camera on by themselves, so you only need this one to SHOW the picture. Needs the player\'s permission.',
    inputs: ['start', 'stop', 'toggle'], outputs: ['ready', 'error', 'stopped'], params: [FACING, P.sel('display', 'Show it', [['corner', 'Small, in a corner'], ['overlay', 'Over the whole game'], ['behind', 'Behind the 3D scene'], ['hidden', 'Hidden']], 'corner'), P.num('opacity', 'Opacity', 1, { min: 0.1, max: 1, step: 0.05 }), P.bool('auto', 'Start automatically', true)],
    init(n, g) { if (n.p.auto) camStart(n, g); }, onInput(n, port, v, g) { if (port === 'toggle') port = n.st.camHeld ? 'stop' : 'start'; if (port === 'start') camStart(n, g); else { camStop(n, g); SN().camShow(g, 'hidden'); g.send(n, 'stopped', true); } } });

  B({ id: 'motionSensor', cat: 'webcam', label: 'Motion Sensor', desc: 'Sees movement in front of the camera (frame differencing – nothing is recorded or sent anywhere). Sends how much is moving (0–100), where (x / y 0–100), exits for "moved" and "still", and swipes: wave left / right / up / down in front of the camera. "zones" is a 3×3 grid of movement (row by row) for touch-free buttons. No camera? Hold N to fake movement.',
    inputs: ['start', 'stop', 'reset'], outputs: ['out', 'moved', 'still', 'x', 'y', 'left', 'right', 'up', 'down', 'zones', 'ready', 'error'],
    params: [FACING, P.num('sensitivity', 'Pixel sensitivity', 28, { min: 8, max: 90, hint: 'smaller = more sensitive' }), P.num('triggerAt', '"Moved" above (%)', 2, { min: 0.2, max: 60, step: 0.2 }), P.num('stillAfter', '"Still" after (s)', 1, { min: 0.2, step: 0.1 }), P.num('swipe', 'Swipe speed (screens/s)', 0.9, { min: 0.2, max: 4, step: 0.1 }), P.num('every', 'Check every (s)', 0.05, { min: 0.02, step: 0.01 }), P.bool('auto', 'Start automatically', true), P.text('variable', 'Save amount (0–100) in variable', '')],
    init(n, g) { n.st.acc = 0; n.st.still = 0; n.st.cx = null; if (n.p.auto) camStart(n, g); },
    onInput(n, port, v, g) { if (port === 'start') camStart(n, g); else if (port === 'stop') camStop(n, g); else { const c = SN().state(g).cam; c.prev = null; } },
    update(n, dt, g) { n.st.acc += dt; if (n.st.acc < U.num(n.p.every, 0.05)) return; const step = n.st.acc; n.st.acc = 0; const S = SN(); let m = n.st.cam ? S.motion(g, U.num(n.p.sensitivity, 28)) : null; if (!m && n.st.sim && g.input.isDown('n')) m = { amount: 0.2, x: 0.5, y: 0.5, cells: [0, 0, 0, 0, 1, 0, 0, 0, 0] }; if (!m) { if (!n.st.sim) return; m = { amount: 0, x: 0.5, y: 0.5, cells: new Array(9).fill(0) }; }
      const pct = Math.min(100, Math.round(m.amount * 1000) / 10 * 3); if (n.p.variable) g.vars[n.p.variable] = pct; g.send(n, 'out', pct); g.send(n, 'zones', m.cells.map((c) => Math.min(100, Math.round(c * 100)))); const moving = pct >= U.num(n.p.triggerAt, 2);
      if (moving) { g.send(n, 'x', Math.round(m.x * 100)); g.send(n, 'y', Math.round(m.y * 100)); n.st.still = 0; if (!n.st.mv) { n.st.mv = true; g.send(n, 'moved', pct); } if (n.st.cx !== null && step > 0) { const vx = (m.x - n.st.cx) / step, vy = (m.y - n.st.cy) / step, T = g.time, sp = U.num(n.p.swipe, 0.9); if (T - (n.st.sw ?? -9) > 0.6) { if (vx > sp) { n.st.sw = T; g.send(n, 'right', vx); } else if (vx < -sp) { n.st.sw = T; g.send(n, 'left', -vx); } else if (vy > sp) { n.st.sw = T; g.send(n, 'down', vy); } else if (vy < -sp) { n.st.sw = T; g.send(n, 'up', -vy); } } } n.st.cx = m.x; n.st.cy = m.y; }
      else { n.st.cx = null; n.st.still += step; if (n.st.mv && n.st.still >= U.num(n.p.stillAfter, 1)) { n.st.mv = false; g.send(n, 'still', true); } } } });

  B({ id: 'colorTracker', cat: 'webcam', label: 'Color Tracker', desc: 'Follows a colour seen by the camera (a ball, a glove, a sticky note) – move a real object to move things in the game. Sends x / y (0–100) and size, and "found" / "lost". Optionally moves an object for you: in 2D across the screen, in 3D across the floor.',
    inputs: ['start', 'stop'], outputs: ['out', 'found', 'lost', 'x', 'y', 'size', 'ready', 'error'],
    params: [FACING, P.color('color', 'Colour to follow', '#ff2d2d'), P.num('tolerance', 'Colour tolerance (°)', 22, { min: 5, max: 90 }), P.num('minSize', 'Ignore smaller than (%)', 0.4, { step: 0.1 }), P.object('follow', 'Move this object', '', [], { hint: 'optional' }), P.num('range', '3D: floor half-size', 6, { min: 1 }), P.num('smooth', 'Smoothing 0–0.95', 0.5, { min: 0, max: 0.95, step: 0.05 }), P.bool('auto', 'Start automatically', true)],
    init(n, g) { if (n.p.auto) camStart(n, g); }, onInput(n, port, v, g) { if (port === 'start') camStart(n, g); else camStop(n, g); },
    update(n, dt, g) { if (!n.st.cam) return; const r = SN().trackColor(g, String(n.p.color || '#ff2d2d'), U.num(n.p.tolerance, 22)); if (!r) return; const found = r.found && r.size * 100 >= U.num(n.p.minSize, 0.4); const e = edge(n, 'f', found); if (e > 0) g.send(n, 'found', true); else if (e < 0) g.send(n, 'lost', true);
      if (!found) return; const k = U.clamp(U.num(n.p.smooth, 0.5), 0, 0.95); n.st.x = (n.st.x ?? r.x) * k + r.x * (1 - k); n.st.y = (n.st.y ?? r.y) * k + r.y * (1 - k); const X = Math.round(n.st.x * 100), Y = Math.round(n.st.y * 100); g.send(n, 'x', X); g.send(n, 'y', Y); g.send(n, 'size', Math.round(r.size * 1000) / 10); g.send(n, 'out', { x: X, y: Y, size: r.size });
      if (n.p.follow) for (const o of objs(g, n, 'follow')) { if (g.dim === '3d') { const R = U.num(n.p.range, 6); o.x = (n.st.x - 0.5) * 2 * R; o.z = (n.st.y - 0.5) * 2 * R; } else { const cv = g.canvas2d; if (cv) { o.x = n.st.x * cv.width; o.y = n.st.y * cv.height; } } } } });

  B({ id: 'lightSensor', cat: 'webcam', label: 'Light Sensor', desc: 'Measures how bright it is in front of the camera (0–100). Fires "dark" when you cover the lens or switch the lights off and "bright" when the light returns – cover the camera to hide in a stealth game. No camera? Hold L to fake darkness.',
    inputs: ['start', 'stop'], outputs: ['out', 'dark', 'bright', 'ready', 'error'], params: [FACING, P.num('darkBelow', 'Dark below (%)', 18, { min: 1, max: 90 }), P.num('brightAbove', 'Bright above (%)', 35, { min: 5, max: 100 }), P.bool('auto', 'Start automatically', true), P.text('variable', 'Save brightness in variable', '')],
    init(n, g) { n.st.state = null; if (n.p.auto) camStart(n, g); }, onInput(n, port, v, g) { if (port === 'start') camStart(n, g); else camStop(n, g); },
    update(n, dt, g) { let b = n.st.cam ? SN().brightness(g) : null; if (b === null && n.st.sim) b = g.input.isDown('l') ? 0.02 : 0.6; if (b === null) return; const pct = Math.round(b * 100); if (n.p.variable) g.vars[n.p.variable] = pct; g.send(n, 'out', pct); if (pct <= U.num(n.p.darkBelow, 18) && n.st.state !== 'dark') { n.st.state = 'dark'; g.send(n, 'dark', pct); } else if (pct >= U.num(n.p.brightAbove, 35) && n.st.state !== 'bright') { n.st.state = 'bright'; g.send(n, 'bright', pct); } } });

  B({ id: 'faceTracker', cat: 'webcam', label: 'Face Tracker', desc: 'Finds a face in the camera picture: x / y (0–100) and size (how close), plus "found" / "lost" – lean in to zoom, move your head to steer. Uses the browser\'s built-in face detection (Chrome / Edge with "Experimental Web Platform features"; Android Chrome). Where it is missing the "error" exit says so.',
    inputs: ['start', 'stop'], outputs: ['out', 'found', 'lost', 'x', 'y', 'size', 'ready', 'error'], params: [FACING, P.num('every', 'Check every (s)', 0.12, { min: 0.05, step: 0.01 }), P.bool('auto', 'Start automatically', true)],
    init(n, g) { if (!('FaceDetector' in window)) { fail(n, g, new Error('Face detection is not supported by this browser')); return; } n.st.det = new window.FaceDetector({ fastMode: true, maxDetectedFaces: 1 }); n.st.acc = 0; if (n.p.auto) camStart(n, g); }, onInput(n, port, v, g) { if (!n.st.det) return; if (port === 'start') camStart(n, g); else camStop(n, g); },
    update(n, dt, g) { if (!n.st.cam || !n.st.det || n.st.busy) return; n.st.acc += dt; if (n.st.acc < U.num(n.p.every, 0.12)) return; n.st.acc = 0; const c = SN().state(g).cam; if (!c.video || c.video.readyState < 2) return; n.st.busy = true; n.st.det.detect(c.video).then((fs) => { n.st.busy = false; const f = fs[0]; const e = edge(n, 'f', !!f); if (e > 0) g.send(n, 'found', true); else if (e < 0) g.send(n, 'lost', true); if (!f) return; const vw = c.video.videoWidth || 640, vh = c.video.videoHeight || 480, b = f.boundingBox; let x = (b.x + b.width / 2) / vw; if (c.mirror) x = 1 - x; const y = (b.y + b.height / 2) / vh, s = b.width / vw; g.send(n, 'x', Math.round(x * 100)); g.send(n, 'y', Math.round(y * 100)); g.send(n, 'size', Math.round(s * 100)); g.send(n, 'out', { x: x * 100, y: y * 100, size: s * 100 }); }).catch(() => { n.st.busy = false; }); } });

  B({ id: 'photoSnap', cat: 'webcam', label: 'Photo', desc: 'Takes a photo with the camera when it receives a signal. The picture is stored as an image text (data URL) in a variable – show it with a label / GUI image, send it to the leaderboard, or download it as a PNG. Photos stay on the device unless you send them somewhere.',
    inputs: ['snap'], outputs: ['out', 'error'], params: [FACING, P.text('variable', 'Save photo in variable', 'photo'), P.num('size', 'Width (px)', 640, { min: 64, max: 1920, step: 32 }), P.bool('download', 'Also download it', false), P.bool('flash', 'Screen flash', true)],
    init(n, g) { camStart(n, g); }, onInput(n, port, v, g) { const c = SN().state(g).cam; if (!n.st.cam || !c.video) return fail(n, g, new Error('The camera is not ready')); const vw = c.video.videoWidth || 640, vh = c.video.videoHeight || 480, W = U.clamp(U.num(n.p.size, 640), 64, 1920), H = Math.round(W * vh / vw); const cv = document.createElement('canvas'); cv.width = W; cv.height = H; const x = cv.getContext('2d'); if (c.mirror) { x.translate(W, 0); x.scale(-1, 1); } x.drawImage(c.video, 0, 0, W, H); const url = cv.toDataURL('image/png');
      if (n.p.variable) g.vars[n.p.variable] = url; if (n.p.download) { const a = document.createElement('a'); a.href = url; a.download = 'photo.png'; a.click(); } if (n.p.flash) { const f = document.createElement('div'); f.style.cssText = 'position:absolute;inset:0;background:#fff;z-index:50;pointer-events:none;opacity:.9;transition:opacity .35s'; g.container.append(f); requestAnimationFrame(() => { f.style.opacity = '0'; }); setTimeout(() => f.remove(), 450); } g.send(n, 'out', url); } });

  /* ======================= 12. VR ======================= */
  B({ id: 'vrMode', cat: 'vr', label: 'VR Mode', desc: 'Puts a 3D game into virtual reality. On a headset browser (WebXR – Quest, SteamVR, …) it enters real VR; everywhere else it switches to a split-screen "cardboard" view you steer with the mouse / arrow keys (or by turning your phone). Shows an "Enter VR" button because browsers only start VR from a click. Exits: entered / exited / unsupported / error. Mode tells you which one is running (webxr or stereo).',
    inputs: ['enter', 'exit', 'toggle'], outputs: ['entered', 'exited', 'unsupported', 'error', 'mode'], params: [P.sel('mode', 'Use', [['auto', 'Headset if available, else split-screen'], ['webxr', 'Headset only'], ['stereo', 'Split-screen only']], 'auto'), P.bool('button', 'Show an "Enter VR" button', true), P.num('ipd', 'Eye distance (mm)', 64, { min: 40, max: 90 })],
    init(n, g) { if (!needs3d(n, g)) return; SN().state(g).vr.ipd = U.num(n.p.ipd, 64) / 1000; SN().vrSupported().then((ok) => { if (!ok && n.p.mode === 'webxr') g.send(n, 'unsupported', true); }); if (n.p.button) { n.st.btn = button(g, 'vr', '🥽 Enter VR', () => this.toggle(n, g)); n.cleanups.push(() => n.st.btn && n.st.btn.remove()); } n.cleanups.push(() => SN().vrExit(g)); },
    toggle(n, g) { const v = SN().state(g).vr; if (v.active) this.leave(n, g); else this.enter(n, g); },
    enter(n, g) { SN().vrEnter(g, n.p.mode).then((m) => { g.send(n, 'mode', m); g.send(n, 'entered', m); if (n.st.btn) n.st.btn.textContent = '✕ Exit VR'; }).catch((e) => fail(n, g, e)); },
    leave(n, g) { SN().vrExit(g); g.send(n, 'exited', true); if (n.st.btn) n.st.btn.textContent = '🥽 Enter VR'; },
    onInput(n, port, v, g) { if (port === 'toggle') this.toggle(n, g); else if (port === 'enter') this.enter(n, g); else this.leave(n, g); } });

  B({ id: 'vrHead', cat: 'vr', label: 'VR Head', desc: 'Where the player\'s head is and where it looks: x / y / z, yaw (turn), pitch (up / down), roll (tilt) every frame. Detects a nod (yes) and a head shake (no) for hands-free menus. Optionally keeps an object (a body, a HUD, a lamp) attached to the head.',
    inputs: [], outputs: ['out', 'x', 'y', 'z', 'yaw', 'pitch', 'roll', 'nod', 'shake'], params: [P.object('attach', 'Keep this object on the head', '', [], { hint: 'optional' }), P.num('offsetY', 'Attach height offset', 0, { step: 0.1 })],
    update(n, dt, g) { const S = SN(), v = S.state(g).vr; if (!v.active) return; S.vrFrame(g); const h = v.head, yaw = (v.mode === 'stereo' ? g.cam3d.yaw + v.rig.yaw : 0) + h.yaw; g.send(n, 'x', h.x); g.send(n, 'y', h.y); g.send(n, 'z', h.z); g.send(n, 'yaw', yaw); g.send(n, 'pitch', h.pitch); g.send(n, 'roll', h.roll); g.send(n, 'out', { x: h.x, y: h.y, z: h.z, yaw, pitch: h.pitch, roll: h.roll });
      if (n.p.attach) for (const o of objs(g, n, 'attach')) { o.x = h.x; o.y = h.y + U.num(n.p.offsetY, 0); o.z = h.z; o.ry = yaw; }
      const hist = n.st.hist || (n.st.hist = []); hist.push({ t: g.time, y: yaw, p: h.pitch }); while (hist.length && g.time - hist[0].t > 1) hist.shift(); if (g.time - (n.st.gest ?? -9) < 1.2 || hist.length < 8) return;
      const rev = (k) => { let c = 0, dir = 0, last = hist[0][k], ext = 0; for (const s of hist) { const d = s[k] - last; if (Math.abs(d) > 3) { const nd = Math.sign(d); if (dir && nd !== dir && Math.abs(last - ext) > 6) c++; if (nd !== dir) { ext = last; } dir = nd; last = s[k]; } } return c; }; const rng = (k) => Math.max(...hist.map((s) => s[k])) - Math.min(...hist.map((s) => s[k]));
      if (rev('p') >= 2 && rng('p') > 12 && rng('y') < 14) { n.st.gest = g.time; hist.length = 0; g.send(n, 'nod', true); } else if (rev('y') >= 2 && rng('y') > 18 && rng('p') < 12) { n.st.gest = g.time; hist.length = 0; g.send(n, 'shake', true); } } });

  B({ id: 'vrController', cat: 'vr', label: 'VR Controller', desc: 'Reads a VR hand controller: trigger, grip, A / B buttons (and releases), thumbstick, position and pointing direction. Optionally keeps an object (a hand, a sword, a torch) in the hand and tells you when the pointer ray is over a target. On desktop (split-screen mode) the mouse is the right hand: left click = trigger, E = grip, Q / F = A / B, W A S D = stick.',
    inputs: [], outputs: ['out', 'trigger', 'triggerUp', 'grip', 'gripUp', 'a', 'b', 'stick', 'x', 'y', 'z', 'pointing'],
    params: [P.sel('hand', 'Hand', [['right', 'Right'], ['left', 'Left']], 'right'), P.object('attach', 'Keep this object in the hand', '', [], { hint: 'optional' }), P.object('pointAt', 'Pointer ray targets', '', [], { hint: 'optional: object name or tag:name' }), P.num('deadzone', 'Stick dead zone', 0.15, { min: 0, max: 0.9, step: 0.05 })],
    update(n, dt, g) { const S = SN(), v = S.state(g).vr; if (!v.active) return; S.vrFrame(g); const c = v.ctrl[n.p.hand]; if (!c || !c.pos) return; const e1 = edge(n, 't', c.trigger > 0.6), e2 = edge(n, 'g', c.grip > 0.6), e3 = edge(n, 'a', c.a > 0.5), e4 = edge(n, 'b', c.b > 0.5);
      if (e1 > 0) g.send(n, 'trigger', c.trigger); if (e1 < 0) g.send(n, 'triggerUp', true); if (e2 > 0) g.send(n, 'grip', c.grip); if (e2 < 0) g.send(n, 'gripUp', true); if (e3 > 0) g.send(n, 'a', true); if (e4 > 0) g.send(n, 'b', true);
      const dz = U.num(n.p.deadzone, 0.15), sx = Math.abs(c.stickX) < dz ? 0 : c.stickX, sy = Math.abs(c.stickY) < dz ? 0 : c.stickY; if (sx || sy) g.send(n, 'stick', { x: sx, y: sy }); g.send(n, 'x', c.pos.x); g.send(n, 'y', c.pos.y); g.send(n, 'z', c.pos.z); g.send(n, 'out', { x: c.pos.x, y: c.pos.y, z: c.pos.z, trigger: c.trigger, grip: c.grip, stickX: sx, stickY: sy });
      if (n.p.attach) for (const o of objs(g, n, 'attach')) { o.x = c.pos.x; o.y = c.pos.y; o.z = c.pos.z; o.ry = U.deg(Math.atan2(-c.dir.x, -c.dir.z)); o.rx = U.deg(Math.asin(U.clamp(c.dir.y, -1, 1))); }
      if (n.p.pointAt) { const ray = { pos: c.pos, dir: c.dir }; let hit = null, bd = 1e9; for (const o of objs(g, n, 'pointAt')) { if (rayHit(ray, o)) { const d = dist(c.pos, pos(o)); if (d < bd) { bd = d; hit = o; } } } if (hit !== n.st.hit) { n.st.hit = hit; if (hit) g.send(n, 'pointing', hit.name); } } } });

  B({ id: 'vrMove', cat: 'vr', label: 'VR Move', desc: 'Moves the player around in VR with the thumbstick: smooth walking, snap turning (comfortable) or teleporting (push forward and release to jump to where the controller points on the floor). Moves the whole play area, so everything the player holds comes along.',
    inputs: ['enable', 'disable'], outputs: ['moved', 'turned', 'teleported'], params: [P.sel('style', 'Style', [['smooth', 'Smooth walking'], ['teleport', 'Teleport'], ['snap', 'Walking + snap turn']], 'smooth'), P.sel('hand', 'Move with', [['left', 'Left stick'], ['right', 'Right stick']], 'left'), P.num('speed', 'Walking speed', 3, { step: 0.5 }), P.num('turn', 'Snap turn angle', 45, { step: 15 }), P.num('floorY', 'Floor height', 0, { step: 0.1 }), P.num('maxJump', 'Teleport range', 12, { step: 1 })],
    init(n) { n.st.on = true; }, onInput(n, port) { n.st.on = port === 'enable'; },
    update(n, dt, g) { if (!n.st.on) return; const S = SN(), v = S.state(g).vr; if (!v.active) return; S.vrFrame(g); const c = v.ctrl[n.p.hand] || v.ctrl.right; if (!c) return; const other = v.ctrl[n.p.hand === 'left' ? 'right' : 'left'], dz = 0.25, sx = Math.abs(c.stickX) < dz ? 0 : c.stickX, sy = Math.abs(c.stickY) < dz ? 0 : c.stickY, yaw = U.rad((v.mode === 'stereo' ? g.cam3d.yaw + v.rig.yaw : 0) + v.head.yaw);
      if (n.p.style === 'teleport') { const up = edge(n, 'tp', sy < -0.6); if (up < 0 && c.pos) { const d = c.dir; if (d.y < -0.02) { const t = (U.num(n.p.floorY, 0) - c.pos.y) / d.y; if (t > 0 && t <= U.num(n.p.maxJump, 12)) { const base = v.base || { x: 0, y: 0, z: 0 }; v.rig.x = c.pos.x + d.x * t - (c.pos.x - v.rig.x - base.x) - base.x; v.rig.z = c.pos.z + d.z * t - (c.pos.z - v.rig.z - base.z) - base.z; g.send(n, 'teleported', { x: c.pos.x + d.x * t, z: c.pos.z + d.z * t }); } } } return; }
      if (sx || sy) { const sp = U.num(n.p.speed, 3) * dt; if (n.p.style === 'smooth' || n.p.style === 'snap') { v.rig.x += (sx * Math.cos(yaw) + sy * Math.sin(yaw)) * sp; v.rig.z += (-sx * Math.sin(yaw) + sy * Math.cos(yaw)) * sp; g.send(n, 'moved', true); } }
      if (n.p.style === 'snap' && other) { const t = edge(n, 'snap', Math.abs(other.stickX) > 0.7); if (t > 0) { v.rig.yaw -= Math.sign(other.stickX) * U.num(n.p.turn, 45); g.send(n, 'turned', v.rig.yaw); } } } });

  B({ id: 'vrGrab', cat: 'vr', label: 'VR Grab', desc: 'Pick things up with a VR hand: squeeze the grip near an object to hold it, let go to drop – or throw it with the speed of your hand. Choose which objects can be grabbed (a tag like tag:grab, or a name).',
    inputs: [], outputs: ['grabbed', 'released', 'out'], params: [P.sel('hand', 'Hand', [['right', 'Right'], ['left', 'Left']], 'right'), P.object('objects', 'Can grab', 'tag:grab', [], { hint: 'tag:name or object name' }), P.num('reach', 'Reach (units)', 0.7, { min: 0.1, step: 0.1 }), P.bool('throw', 'Throw when released', true), P.num('throwPower', 'Throw power', 1.3, { step: 0.1 })],
    update(n, dt, g) { const S = SN(), v = S.state(g).vr; if (!v.active) return; S.vrFrame(g); const c = v.ctrl[n.p.hand]; if (!c || !c.pos) return; const vel = n.st.lp ? { x: (c.pos.x - n.st.lp.x) / Math.max(dt, 1e-3), y: (c.pos.y - n.st.lp.y) / Math.max(dt, 1e-3), z: (c.pos.z - n.st.lp.z) / Math.max(dt, 1e-3) } : { x: 0, y: 0, z: 0 }; n.st.lp = { x: c.pos.x, y: c.pos.y, z: c.pos.z }; n.st.vel = n.st.vel ? { x: n.st.vel.x * 0.6 + vel.x * 0.4, y: n.st.vel.y * 0.6 + vel.y * 0.4, z: n.st.vel.z * 0.6 + vel.z * 0.4 } : vel;
      const e = edge(n, 'gr', c.grip > 0.6);
      if (e > 0 && !n.st.held) { let best = null, bd = 1e9; for (const o of objs(g, n, 'objects')) { const d = dist(c.pos, pos(o)) - rad(o) * (o.scale || 1); if (d <= U.num(n.p.reach, 0.7) && d < bd) { bd = d; best = o; } } if (best) { n.st.held = best; n.st.prevBody = best.physics && best.physics.body; if (best.physics) best.physics.body = 'kinematic'; v.grabbed.set(n.p.hand, best); g.send(n, 'grabbed', best.name); } }
      if (n.st.held) { const o = n.st.held; if (!o.alive) { n.st.held = null; return; } o.x = c.pos.x; o.y = c.pos.y; o.z = c.pos.z; o.vx = o.vy = o.vz = 0; g.send(n, 'out', o.name);
        if (e < 0) { if (o.physics && n.st.prevBody !== undefined) o.physics.body = n.st.prevBody; if (n.p.throw) { const k = U.num(n.p.throwPower, 1.3); o.vx = n.st.vel.x * k; o.vy = n.st.vel.y * k; o.vz = n.st.vel.z * k; } v.grabbed.delete(n.p.hand); g.send(n, 'released', o.name); n.st.held = null; } } } });

  B({ id: 'vrHaptic', cat: 'vr', label: 'VR Haptics', desc: 'Makes a VR controller buzz – feel a hit, a button, a heartbeat. On a phone it vibrates the device; on desktop the view shakes briefly.',
    inputs: ['in'], outputs: ['out'], params: [P.sel('hand', 'Hand', [['right', 'Right'], ['left', 'Left'], ['both', 'Both']], 'right'), P.num('strength', 'Strength 0–1', 0.7, { min: 0.05, max: 1, step: 0.05 }), P.num('ms', 'Duration (ms)', 120, { min: 20, max: 2000, step: 10 })],
    onInput(n, port, v, g) { const st = SN().state(g).vr; const hands = n.p.hand === 'both' ? ['left', 'right'] : [n.p.hand]; let done = false; for (const h of hands) { const gp = st.ctrl[h] && st.ctrl[h].src && st.ctrl[h].src.gamepad; const act = gp && ((gp.hapticActuators && gp.hapticActuators[0]) || gp.vibrationActuator); if (act) { try { if (act.pulse) act.pulse(U.num(n.p.strength, 0.7), U.num(n.p.ms, 120)); else act.playEffect('dual-rumble', { duration: U.num(n.p.ms, 120), strongMagnitude: U.num(n.p.strength, 0.7), weakMagnitude: U.num(n.p.strength, 0.7) }); done = true; } catch { /* no haptics */ } } }
      if (!done) { if (navigator.vibrate) navigator.vibrate(U.num(n.p.ms, 120)); else if (g.cam3d) g.cam3d.shake = Math.max(g.cam3d.shake || 0, 2); } g.send(n, 'out', v); } });

  B({ id: 'vrGaze', cat: 'vr', label: 'VR Gaze', desc: 'Select things just by looking at them: look at an object for a moment and "selected" fires (a progress value 0–1 lets you draw a filling ring). Perfect for cardboard-style VR with no controllers, and for AR. Works in VR, AR and normal 3D.',
    inputs: [], outputs: ['looking', 'selected', 'lookAway', 'progress'], params: [P.object('target', 'Look at', 'self', ['self'], { hint: 'object name or tag:name' }), P.num('seconds', 'Hold for (s)', 1.2, { min: 0.2, step: 0.1 }), P.num('range', 'Max distance', 30, { min: 1 })],
    update(n, dt, g) { if (g.dim !== '3d') return; const ray = headRay(g); let hit = false; for (const o of objs(g, n, 'target')) { if (rayHit(ray, o) && dist(ray.pos, pos(o)) <= U.num(n.p.range, 30)) { hit = true; break; } }
      if (hit) { n.st.t = (n.st.t || 0) + dt; if (!n.st.on) { n.st.on = true; g.send(n, 'looking', true); } const p = Math.min(1, n.st.t / U.num(n.p.seconds, 1.2)); g.send(n, 'progress', p); if (p >= 1 && !n.st.done) { n.st.done = true; g.send(n, 'selected', true); } } else if (n.st.on) { n.st.on = false; n.st.t = 0; n.st.done = false; g.send(n, 'progress', 0); g.send(n, 'lookAway', true); } } });

  /* ======================= 13. AR ======================= */
  const arEnsure = (n, g) => { if (!needs3d(n, g)) return false; return true; };
  B({ id: 'arMode', cat: 'ar', label: 'AR Mode', desc: 'Turns a 3D game into augmented reality: your 3D objects appear in the real world. On AR phones / headsets (WebXR) it uses real surface tracking; everywhere else it falls back to the camera picture behind the game with the view steered by tilting the phone (or mouse / arrow keys on a computer). Shows a "Start AR" button because browsers only start AR from a click.',
    inputs: ['start', 'stop', 'toggle'], outputs: ['started', 'stopped', 'unsupported', 'error', 'mode'], params: [P.sel('mode', 'Use', [['auto', 'Real AR if available, else camera'], ['webxr', 'Real AR only (WebXR)'], ['camera', 'Camera background only']], 'auto'), FACING, P.bool('button', 'Show a "Start AR" button', true)],
    init(n, g) { if (!arEnsure(n, g)) return; if (n.p.button) { n.st.btn = button(g, 'ar', '📷 Start AR', () => this.toggle(n, g)); n.cleanups.push(() => n.st.btn && n.st.btn.remove()); } n.cleanups.push(() => SN().arExit(g)); },
    toggle(n, g) { if (SN().state(g).ar.active) this.leave(n, g); else this.enter(n, g); },
    enter(n, g) { SN().arEnter(g, n.p.mode, n.p.facing === 'user' ? 'user' : 'environment').then((m) => { g.send(n, 'mode', m); g.send(n, 'started', m); if (n.st.btn) n.st.btn.textContent = '✕ Stop AR'; }).catch((e) => { if (/not supported/i.test(e.message)) g.send(n, 'unsupported', true); fail(n, g, e); }); },
    leave(n, g) { SN().arExit(g); g.send(n, 'stopped', true); if (n.st.btn) n.st.btn.textContent = '📷 Start AR'; },
    onInput(n, port, v, g) { if (!arEnsure(n, g)) return; if (port === 'toggle') this.toggle(n, g); else if (port === 'start') this.enter(n, g); else this.leave(n, g); } });

  B({ id: 'arSurface', cat: 'ar', label: 'AR Surface', desc: 'Finds the floor or table in front of the player and shows a placement ring on it. Sends "found" / "lost" and the x / y / z of the spot. With real AR it uses the device\'s surface detection; with the camera fallback it uses a flat floor at the height you set. Feed x / y / z into AR Place or any Position block.',
    inputs: [], outputs: ['out', 'found', 'lost', 'x', 'y', 'z'], params: [P.num('floorY', 'Floor height (fallback)', 0, { step: 0.1 }), P.bool('reticle', 'Show the placement ring', true), P.color('color', 'Ring colour', '#ffffff')],
    update(n, dt, g) { if (g.dim !== '3d') return; const S = SN(), a = S.state(g).ar; if (!a.active) return; const h = S.arSurface(g, U.num(n.p.floorY, 0)); const e = edge(n, 'f', !!h); if (e > 0) g.send(n, 'found', true); else if (e < 0) g.send(n, 'lost', true);
      if (n.p.reticle && g.scene3d) { if (!a.reticle) { const T = g.THREE; a.reticle = new T.Mesh(new T.RingGeometry(0.1, 0.14, 40).rotateX(-Math.PI / 2), new T.MeshBasicMaterial({ color: n.p.color || '#ffffff', transparent: true, opacity: 0.9, depthTest: false })); a.reticle.renderOrder = 99; g.scene3d.add(a.reticle); n.cleanups.push(() => { if (a.reticle && a.reticle.parent) a.reticle.parent.remove(a.reticle); a.reticle = null; }); } a.reticle.visible = !!h; if (h) a.reticle.position.set(h.x, h.y + 0.005, h.z); }
      if (h) { g.send(n, 'x', h.x); g.send(n, 'y', h.y); g.send(n, 'z', h.z); g.send(n, 'out', h); } } });

  B({ id: 'arPlace', cat: 'ar', label: 'AR Place', desc: 'Puts an object onto the surface found by AR Surface – tap the screen (or send the "place" signal) and it appears there. Choose to MOVE an object that is already in the scene, or SPAWN a new copy of a prefab each time. Can turn to face the player and scale to real-world size.',
    inputs: ['place'], outputs: ['placed', 'out', 'error'], params: [P.sel('how', 'On tap', [['move', 'Move an existing object'], ['spawn', 'Spawn a new copy']], 'move'), P.object('object', 'Object / prefab', '', [], { hint: 'name of the object or prefab' }), P.num('scale', 'Scale (1 = as designed)', 1, { min: 0.01, step: 0.1 }), P.bool('face', 'Turn to face the player', true), P.num('lift', 'Lift above surface', 0, { step: 0.05 }), P.bool('tap', 'Place when the screen is tapped', true)],
    init(n, g) { if (n.p.tap) n.cleanups.push(g.input.on('mousedown', () => this.doPlace(n, g))); },
    onInput(n, port, v, g) { this.doPlace(n, g); },
    doPlace(n, g) { if (g.dim !== '3d') return; const S = SN(), a = S.state(g).ar; if (!a.active || !a.found || !a.hit) return; const h = a.hit; let o = null;
      if (n.p.how === 'spawn') { try { o = g.spawn(String(n.p.object || ''), { x: h.x, y: h.y + U.num(n.p.lift, 0), z: h.z }); } catch (e) { return fail(n, g, e); } } else { o = g.targets(n.p.object || 'self', n.owner, null)[0]; if (o) { o.x = h.x; o.y = h.y + U.num(n.p.lift, 0); o.z = h.z; o.vx = o.vy = o.vz = 0; } }
      if (!o) return fail(n, g, new Error('AR Place: object "' + n.p.object + '" not found')); const sc = U.num(n.p.scale, 1); if (sc !== 1) { o.w *= sc; o.h *= sc; o.d *= sc; } if (n.p.face) { const c = a.cam || g.cam3d.pos; o.ry = U.deg(Math.atan2(c.x - o.x, c.z - o.z)); } o.dirty3d = true; g.send(n, 'placed', o.name); g.send(n, 'out', { x: h.x, y: h.y, z: h.z }); } });

  B({ id: 'arScale', cat: 'ar', label: 'AR Pinch & Turn', desc: 'Lets the player resize and turn an object with their fingers: pinch to scale, drag with two fingers sideways to rotate. On a computer use the mouse wheel to scale and hold Shift + wheel to rotate.',
    inputs: [], outputs: ['scaled', 'turned'], params: [P.object('target', 'Object', 'self', ['self']), P.num('min', 'Smallest scale', 0.2, { step: 0.1 }), P.num('max', 'Biggest scale', 5, { step: 0.5 }), P.bool('rotate', 'Allow turning', true)],
    init(n, g) { const apply = (f) => { for (const o of objs(g, n, 'target')) { const base = o.__arBase || (o.__arBase = { w: o.w, h: o.h, d: o.d, s: 1 }); const s = U.clamp(base.s * f, U.num(n.p.min, 0.2), U.num(n.p.max, 5)); base.s = s; o.w = base.w * s; o.h = base.h * s; o.d = base.d * s; o.dirty3d = true; g.send(n, 'scaled', s); } };
      n.cleanups.push(g.input.on('gesture', (e) => { if (e.type === 'pinch') { const f = e.scale / (n.st.ls || 1); n.st.ls = e.scale; apply(Math.pow(f, 1)); } })); n.cleanups.push(g.input.on('wheel', (e) => { if (g.input.isDown('shift')) { if (!n.p.rotate) return; for (const o of objs(g, n, 'target')) { o.ry = (o.ry || 0) + e.delta * 0.2; o.dirty3d = true; g.send(n, 'turned', o.ry); } } else apply(e.delta < 0 ? 1.08 : 0.93); })); },
    update(n, dt, g) { if (!g.input.touches || !g.input.touches.length) n.st.ls = 1; } });

  B({ id: 'arLight', cat: 'ar', label: 'AR Light Match', desc: 'Makes virtual objects match the real room: the camera measures how bright it is and the game\'s lights are dimmed or boosted to fit, so a model looks natural in a dark room and in sunlight. Needs the camera (starts it if AR has not).',
    inputs: [], outputs: ['out'], params: [FACING, P.num('strength', 'Strength 0–2', 1, { min: 0, max: 2, step: 0.1 }), P.num('dark', 'Lowest light (×)', 0.25, { min: 0, max: 1, step: 0.05 }), P.num('bright', 'Brightest light (×)', 1.3, { min: 0.5, max: 3, step: 0.05 }), P.num('smooth', 'Smoothing 0–0.98', 0.9, { min: 0, max: 0.98, step: 0.02 })],
    init(n, g) { camStart(n, g); }, 
    update(n, dt, g) { if (g.dim !== '3d' || !g.scene3d) return; let b = n.st.cam ? SN().brightness(g) : null; if (b === null) return; const k = U.clamp(U.num(n.p.smooth, 0.9), 0, 0.98); n.st.b = (n.st.b ?? b) * k + b * (1 - k); const f = 1 + (U.clamp(U.num(n.p.dark, 0.25) + (U.num(n.p.bright, 1.3) - U.num(n.p.dark, 0.25)) * Math.min(1, n.st.b * 1.4), 0, 5) - 1) * U.num(n.p.strength, 1);
      g.scene3d.traverse((l) => { if (l.isLight) { if (l.userData.vxBase === undefined) l.userData.vxBase = l.intensity; l.intensity = l.userData.vxBase * f; } }); g.send(n, 'out', Math.round(f * 100) / 100); } , });

  B({ id: 'arShadowFloor', cat: 'ar', label: 'AR Shadow Floor', desc: 'An invisible floor that only shows shadows, so virtual objects look like they sit on the real table or ground. Needs a light that casts shadows (turn on "Cast shadows" on a Directional or Spot light).',
    inputs: [], outputs: [], params: [P.num('floorY', 'Floor height', 0, { step: 0.05 }), P.num('size', 'Size', 40, { min: 2 }), P.num('opacity', 'Shadow strength', 0.45, { min: 0.05, max: 1, step: 0.05 })],
    init(n, g) { if (!needs3d(n, g) || !g.scene3d) return; const T = g.THREE; const m = new T.Mesh(new T.PlaneGeometry(U.num(n.p.size, 40), U.num(n.p.size, 40)).rotateX(-Math.PI / 2), new T.ShadowMaterial({ opacity: U.num(n.p.opacity, 0.45) })); m.position.y = U.num(n.p.floorY, 0); m.receiveShadow = true; g.scene3d.add(m); g.renderer3d.shadowMap.enabled = true; n.cleanups.push(() => { if (m.parent) m.parent.remove(m); m.geometry.dispose(); m.material.dispose(); }); } });

  B({ id: 'arDistance', cat: 'ar', label: 'AR Distance', desc: 'Measures the real-world distance between the player\'s device (type "camera") and an object, or between two objects – a tape measure, a "come closer" prompt, or an object that wakes up when you walk up to it. Sends the distance and "near" / "far" when crossing your limit.',
    inputs: [], outputs: ['out', 'near', 'far'], params: [P.object('from', 'From', 'camera', ['camera', 'self']), P.object('to', 'To', 'self', ['camera', 'self']), P.num('limit', '"Near" within', 1.5, { min: 0.05, step: 0.05 }), P.text('variable', 'Save distance in variable', '')],
    update(n, dt, g) { const S = SN(), a = S.state(g), v = a.vr; const at = (spec) => { if (String(spec) === 'camera') { const r = v.active ? { x: v.head.x, y: v.head.y, z: v.head.z } : (a.ar.cam || g.cam3d.pos); return r; } const o = g.targets(spec || 'self', n.owner, null)[0]; return o ? pos(o) : null; }; const A = at(n.p.from), Bp = at(n.p.to); if (!A || !Bp) return; const d = dist(A, Bp); if (n.p.variable) g.vars[n.p.variable] = Math.round(d * 100) / 100; g.send(n, 'out', Math.round(d * 100) / 100);
      const near = d <= U.num(n.p.limit, 1.5), e = edge(n, 'nr', near); if (e > 0) g.send(n, 'near', d); else if (e < 0) g.send(n, 'far', d); } });
})();
